import type { DatasetId } from '../data/datasets'

export interface Lesson {
  id: string
  moduleId: string
  title: string
  duration: string
  level: string
  dataset: DatasetId
  ordered: boolean
  objective: string
  theory: string[]
  syntax: string
  example: string
  explanation: string
  exercise: string
  hints: string[]
  solution: string
  summary: string[]
  criteria: string
  starter: string
  manual?: { prompt: string; rubric: string[]; sample: string }
}

export interface Module {
  id: string
  number: number
  title: string
  description: string
  lessons: Lesson[]
}

type LessonContent = Omit<Lesson, 'moduleId' | 'duration' | 'level' | 'dataset'>
function module(number: number, title: string, description: string, lessons: LessonContent[]): Module {
  const id = `m${number}`
  return {
    id, number, title, description,
    lessons: lessons.map(item => ({
      ...item, moduleId: id, duration: number < 4 ? '15–20 min' : '25–30 min',
      level: number < 3 ? 'Pemula' : number < 5 ? 'Pemula+' : 'Menengah',
      dataset: number < 6 ? 'small' : 'retail',
    })),
  }
}

// Diskon adalah total rupiah per baris. Harga katalog tidak dipakai untuk revenue historis.
const monthlyRevenue = `SELECT strftime('%Y-%m', o.order_date) AS bulan,
       COUNT(DISTINCT o.order_id) AS transaksi,
       SUM(d.quantity * d.unit_price - d.discount) AS revenue
FROM orders AS o
JOIN order_details AS d ON d.order_id = o.order_id
WHERE o.status = 'completed'
GROUP BY strftime('%Y-%m', o.order_date)`

