      syntax: "WITH frekuensi AS (...) SELECT CASE WHEN transaksi = 0 THEN 'belum' WHEN transaksi = 1 THEN 'sekali' ELSE 'berulang' END AS segmen, COUNT(*) FROM frekuensi GROUP BY segmen;",
